namespace sv_d9c6fee15e9b40db8b5ae3e46f3e3831.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@using sv_d9c6fee15e9b40db8b5ae3e46f3e3831.Models
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger mt-3">@ErrorMessage</div>
}

@* Step Content *@
<div class="step-content mt-4">
    @switch (CurrentStep)
    {
        case 0:
            @RenderPersonalInfo();
            break;
        case 1:
            @RenderWorkHistory();
            break;
        case 2:
            @RenderReferences();
            break;
        case 3:
            @RenderCoverLetter();
            break;
        case 4:
            @RenderReviewSubmit();
            break;
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private string ErrorMessage { get; set; } = string.Empty;
    private bool IsSubmitting { get; set; }
    private int? SubmittedApplicationId { get; set; }

    // Form state
    private string FullName { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;
    private string Address { get; set; } = string.Empty;

    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    private string CoverLetter { get; set; } = string.Empty;
    private const int CoverLetterMaxChars = 2000;

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "dimmed";
    }

    private void NavigateToStep(int step)
    {
        if (step < CurrentStep)
        {
            CurrentStep = step;
            ErrorMessage = string.Empty;
        }
    }

    private async Task NextStep()
    {
        ErrorMessage = string.Empty;

        if (!ValidateCurrentStep())
            return;

        if (CurrentStep == 0)
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                ErrorMessage = "The email address is not valid. Please check and try again.";
                return;
            }
        }

        CurrentStep++;
    }

    private void PreviousStep()
    {
        if (CurrentStep > 0)
        {
            CurrentStep--;
            ErrorMessage = string.Empty;
        }
    }

    private bool ValidateCurrentStep()
    {
        switch (CurrentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(FullName))
                { ErrorMessage = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(Email))
                { ErrorMessage = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(Phone))
                { ErrorMessage = "Phone is required."; return false; }
                if (string.IsNullOrWhiteSpace(Address))
                { ErrorMessage = "Address is required."; return false; }
                return true;
            case 1:
                foreach (var entry in WorkEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company))
                    { ErrorMessage = "Company name is required for all entries."; return false; }
                    if (string.IsNullOrWhiteSpace(entry.Title))
                    { ErrorMessage = "Job title is required for all entries."; return false; }
                    if (entry.StartDate == default)
                    { ErrorMessage = "Start date is required for all entries."; return false; }
                    if (string.IsNullOrWhiteSpace(entry.Description))
                    { ErrorMessage = "Description is required for all entries."; return false; }
                }
                return true;
            case 2:
                foreach (var r in References)
                {
                    if (string.IsNullOrWhiteSpace(r.Name))
                    { ErrorMessage = "Name is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Relationship))
                    { ErrorMessage = "Relationship is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Email))
                    { ErrorMessage = "Email is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Phone))
                    { ErrorMessage = "Phone is required for all references."; return false; }
                }
                return true;
            case 3:
                if (string.IsNullOrWhiteSpace(CoverLetter))
                { ErrorMessage = "Cover letter is required."; return false; }
                if (CoverLetter.Length > CoverLetterMaxChars)
                { ErrorMessage = $"Cover letter must be {CoverLetterMaxChars} characters or fewer."; return false; }
                return true;
            default:
                return true;
        }
    }

    private async Task SubmitApplication()
    {
        IsSubmitting = true;
        ErrorMessage = string.Empty;

        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var references = References.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, workHistory, references, CoverLetter);
            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }

    private void AddWorkEntry()
    {
        WorkEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(WorkEntryModel entry)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.Remove(entry);
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(ReferenceModel reference)
    {
        if (References.Count > 2)
            References.Remove(reference);
    }

    // Mutable model classes for form binding
    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }

    // Render fragments for each step
    private RenderFragment RenderPersonalInfo() => __builder =>
    {
        <h3>Personal Information</h3>
        <div class="mb-3">
            <label class="form-label">Full Name</label>
            <input type="text" class="form-control" @bind="FullName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="Email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone</label>
            <input type="tel" class="form-control" @bind="Phone" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address</label>
            <input type="text" class="form-control" @bind="Address" />
        </div>
        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderWorkHistory() => __builder =>
    {
        <h3>Work History</h3>
        @for (int i = 0; i < WorkEntries.Count; i++)
        {
            var entry = WorkEntries[i];
            <div class="card mb-3 p-3">
                <h5>Position @(i + 1)</h5>
                <div class="mb-2">
                    <label class="form-label">Company</label>
                    <input type="text" class="form-control" @bind="entry.Company" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Job Title</label>
                    <input type="text" class="form-control" @bind="entry.Title" />
                </div>
                <div class="row mb-2">
                    <div class="col-md-5">
                        <label class="form-label">Start Date</label>
                        <input type="date" class="form-control" @bind="entry.StartDate" />
                    </div>
                    <div class="col-md-5">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                    </div>
                    <div class="col-md-2 d-flex align-items-end">
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input" @bind="entry.IsCurrent" />
                            <label class="form-check-label">Current</label>
                        </div>
                    </div>
                </div>
                <div class="mb-2">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="3" @bind="entry.Description"></textarea>
                </div>
                @if (WorkEntries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(entry)">Remove</button>
                }
            </div>
        }
        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">Add Another Position</button>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderReferences() => __builder =>
    {
        <h3>References</h3>
        @for (int i = 0; i < References.Count; i++)
        {
            var reference = References[i];
            <div class="card mb-3 p-3">
                <h5>Reference @(i + 1)</h5>
                <div class="mb-2">
                    <label class="form-label">Name</label>
                    <input type="text" class="form-control" @bind="reference.Name" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Relationship</label>
                    <input type="text" class="form-control" @bind="reference.Relationship" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="reference.Email" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Phone</label>
                    <input type="tel" class="form-control" @bind="reference.Phone" />
                </div>
                @if (References.Count > 2)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(reference)">Remove</button>
                }
            </div>
        }
        @if (References.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">Add Reference</button>
        }
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderCoverLetter() => __builder =>
    {
        <h3>Cover Letter</h3>
        <div class="mb-3">
            <textarea class="form-control" rows="10" @bind="CoverLetter"></textarea>
            <div class="form-text">@(CoverLetter?.Length ?? 0) / @CoverLetterMaxChars characters</div>
        </div>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderReviewSubmit() => __builder =>
    {
        if (SubmittedApplicationId.HasValue)
        {
            <div class="alert alert-success">
                <h4>Application Submitted Successfully!</h4>
                <p>Your application ID is: <strong>@SubmittedApplicationId.Value</strong></p>
            </div>
        }
        else
        {
            <h3>Review & Submit</h3>

            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Personal Information</h5>
                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(0)'>Edit</a>
                </div>
                <p><strong>Name:</strong> @FullName</p>
                <p><strong>Email:</strong> @Email</p>
                <p><strong>Phone:</strong> @Phone</p>
                <p><strong>Address:</strong> @Address</p>
            </div>

            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Work History</h5>
                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(1)'>Edit</a>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-2 ps-3 border-start">
                        <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
                        <p class="mb-1 text-muted">@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</p>
                        <p class="mb-0">@entry.Description</p>
                    </div>
                }
            </div>

            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>References</h5>
                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(2)'>Edit</a>
                </div>
                @foreach (var r in References)
                {
                    <div class="mb-2 ps-3 border-start">
                        <p class="mb-1"><strong>@r.Name</strong> (@r.Relationship)</p>
                        <p class="mb-0">@r.Email | @r.Phone</p>
                    </div>
                }
            </div>

            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Cover Letter</h5>
                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(3)'>Edit</a>
                </div>
                <p style="white-space: pre-wrap;">@CoverLetter</p>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-success" @onclick="SubmitApplication" disabled="@IsSubmitting">
                    @(IsSubmitting ? "Submitting..." : "Submit Application")
                </button>
            </div>
        }
    };
}

<style>
    .step-indicator {
        display: flex;
        align-items: center;
        justify-content: center;
        margin: 1.5rem 0;
    }

    .step {
        display: flex;
        flex-direction: column;
        align-items: center;
        cursor: default;
        min-width: 80px;
    }

    .step.completed {
        cursor: pointer;
    }

    .step-circle {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: bold;
        font-size: 0.9rem;
        border: 2px solid #dee2e6;
        background: #fff;
        color: #6c757d;
    }

    .step.active .step-circle {
        border-color: #0d6efd;
        background: #0d6efd;
        color: #fff;
    }

    .step.completed .step-circle {
        border-color: #198754;
        background: #198754;
        color: #fff;
    }

    .step.dimmed .step-circle {
        opacity: 0.5;
    }

    .step-label {
        font-size: 0.75rem;
        margin-top: 0.3rem;
        text-align: center;
        color: #6c757d;
    }

    .step.active .step-label {
        color: #0d6efd;
        font-weight: 600;
    }

    .step.completed .step-label {
        color: #198754;
    }

    .step.dimmed .step-label {
        opacity: 0.5;
    }

    .step-connector {
        flex: 1;
        height: 2px;
        background: #dee2e6;
        margin: 0 0.5rem;
        margin-bottom: 1.2rem;
    }
</style>

