                </div>
                <div class="mb-2">
                    <label class="form-label">Relationship</label>
                    <input type="text" class="form-control" @bind="reference.Relationship" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="reference.Email" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Phone</label>
                    <input type="tel" class="form-control" @bind="reference.Phone" />
                </div>
                @if (References.Count > 2)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(reference)">Remove</button>
                }
            </div>
        }
        @if (References.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">Add Reference</button>
        }
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderCoverLetter() => __builder =>
    {
        <h3>Cover Letter</h3>
        <div class="mb-3">
            <textarea class="form-control" rows="10" @bind="CoverLetter"></textarea>
            <div class="form-text">@(CoverLetter?.Length ?? 0) / @CoverLetterMaxChars characters</div>
        </div>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    };

    private RenderFragment RenderReviewSubmit() => __builder =>
    {
        if (SubmittedApplicationId.HasValue)
        {
            <div class="alert alert-success">
                <h4>Application Submitted Successfully!</h4>
                <p>Your application ID is: <strong>@SubmittedApplicationId.Value</strong></p>
            </div>
        }
        else
        {
            <h3>Review & Submit</h3>

            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Personal Information</h5>
                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(0)'>Edit</a>
                </div>
                <p><strong>Name:</strong> @FullName</p>
                <p><strong>Email:</strong> @Email</p>
                <p><strong>Phone:</strong> @Phone</p>
                <p><strong>Address:</strong> @Address</p>
            </div>

            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Work History</h5>
                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(1)'>Edit</a>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-2 ps-3 border-start">
                        <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
                        <p class="mb-1 text-muted">@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</p>
                        <p class="mb-0">@entry.Description</p>
                    </div>
